import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.math.BigDecimal;import java.text.DecimalFormat;import java.util.*;

/** v6.3: quantity steppers, validation, price memory, data export, cleaner PDF header. */
public class OrganizerRebuildV63Activity extends OrganizerRebuildV62Activity {
    private static final int SAVE_PDF_63=6303, SAVE_DATA_63=6304;
    private final Handler ui=new Handler(Looper.getMainLooper());
    private ViewTreeObserver.OnGlobalLayoutListener gl;
    private final HashSet<View> decorated=Collections.newSetFromMap(new WeakHashMap<View,Boolean>());
    private final HashMap<String,String> catalogCategories=new HashMap<>();
    private File pendingPdf,pendingData;
    private final DecimalFormat money=new DecimalFormat("#,##0.##");
    private final int NAVY=Color.rgb(19,50,76), TEAL=Color.rgb(28,196,163), TEAL_DARK=Color.rgb(18,158,132), MUTED=Color.rgb(118,132,146), BORDER=Color.rgb(224,230,236);

    @Override public void onCreate(Bundle b){super.onCreate(b);loadCatalogNames();View r=findViewById(android.R.id.content);if(r!=null){gl=()->{ui.removeCallbacks(refresh);ui.postDelayed(refresh,65);};r.getViewTreeObserver().addOnGlobalLayoutListener(gl);}ui.postDelayed(refresh,120);}
    @Override protected void onDestroy(){View r=findViewById(android.R.id.content);if(r!=null&&gl!=null&&r.getViewTreeObserver().isAlive())r.getViewTreeObserver().removeOnGlobalLayoutListener(gl);ui.removeCallbacks(refresh);super.onDestroy();}

    private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} private String lang(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("lang","ar");} private boolean rtl(){return!"en".equals(lang());} private String tx(String e,String a,String k){return"ar".equals(lang())?a:("ku".equals(lang())?k:e);} private boolean eq(String s,String e,String a,String k){return s.equals(e)||s.equals(a)||s.equals(k);}
    private GradientDrawable bg(int fill,int stroke,int radius){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(radius));if(stroke!=0)g.setStroke(dp(1),stroke);return g;}
    private Button smallBtn(String s,int type){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(10);b.setTypeface(Typeface.DEFAULT_BOLD);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(7),0,dp(7),0);int fill=Color.WHITE,stroke=BORDER,fg=NAVY;if(type==1){fill=TEAL;stroke=TEAL;fg=Color.WHITE;}else if(type==2){stroke=TEAL;fg=TEAL_DARK;}else if(type==4){fill=Color.rgb(255,247,247);stroke=Color.rgb(238,200,200);fg=Color.rgb(185,65,65);}b.setTextColor(fg);b.setBackground(bg(fill,stroke,13));return b;}
    private TextView text(String s,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);t.setGravity(rtl()?Gravity.RIGHT:Gravity.LEFT);return t;}

    private final Runnable refresh=()->{persistVisiblePrices();View r=findViewById(android.R.id.content);if(r!=null)walk(r);};
    private void walk(View v){
        if(v instanceof LinearLayout){ViewGroup g=(ViewGroup)v;Object item=findItemForCard(g);if(item!=null&&!decorated.contains(v)){decorateQuantity(g,item);decorated.add(v);}}
        if(v instanceof Button){Button b=(Button)v;String s=String.valueOf(b.getText()).trim();
            if(eq(s,"Share PDF","مشاركة PDF","PDF هاوبەش بکە"))b.setOnClickListener(x->{if(!validateForExport())return;pendingPdf=makePdf63();if(pendingPdf!=null)shareFile(pendingPdf,"application/pdf",tx("Share PDF","مشاركة PDF","PDF هاوبەش بکە"));});
            else if(eq(s,"Save PDF","حفظ PDF","PDF پاشەکەوت بکە"))b.setOnClickListener(x->{if(!validateForExport())return;pendingPdf=makePdf63();if(pendingPdf!=null){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,pendingPdf.getName());startActivityForResult(i,SAVE_PDF_63);}});
        }
        if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)walk(g.getChildAt(i));}
        if(isPreviewRoot(v)&&v instanceof LinearLayout&&!decorated.contains(v)){addExportDataButton((LinearLayout)v);decorated.add(v);}
        interceptCatalogCards(v);
    }

    private boolean isPreviewRoot(View v){if(!(v instanceof LinearLayout))return false;return contains(v,new String[]{"Form preview","معاينة الاستمارة","پێشبینینی فۆرم"})&&contains(v,new String[]{"Share PDF","مشاركة PDF","PDF هاوبەش بکە"});}
    private boolean contains(View v,String[] vals){if(v instanceof TextView){String s=String.valueOf(((TextView)v).getText()).trim();for(String x:vals)if(x.equals(s))return true;}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),vals))return true;}return false;}

    private void addExportDataButton(LinearLayout root){Button data=smallBtn(tx("Export form data","تصدير بيانات الاستمارة","داتای فۆرم هەناردە بکە"),2);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(34));lp.topMargin=dp(6);root.addView(data,Math.max(0,root.getChildCount()-1),lp);data.setOnClickListener(v->{if(!validateForExport())return;pendingData=makeDataFile();if(pendingData!=null){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,pendingData.getName());startActivityForResult(i,SAVE_DATA_63);}});}

    private void decorateQuantity(ViewGroup card,Object item){String name=get(item,"name");if(name.isEmpty()||!containsExact(card,name))return;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);TextView label=text(tx("Quantity","الكمية","بڕ"),10,true,MUTED);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));Button minus=smallBtn("−",2);TextView qty=text(get(item,"qty").isEmpty()?"1":get(item,"qty"),12,true,NAVY);qty.setGravity(Gravity.CENTER);qty.setBackground(bg(Color.rgb(244,250,249),BORDER,12));Button plus=smallBtn("+",2);row.addView(minus,new LinearLayout.LayoutParams(dp(36),dp(32)));LinearLayout.LayoutParams qlp=new LinearLayout.LayoutParams(dp(52),dp(32));qlp.leftMargin=dp(4);qlp.rightMargin=dp(4);row.addView(qty,qlp);row.addView(plus,new LinearLayout.LayoutParams(dp(36),dp(32)));minus.setOnClickListener(v->changeQty(item,-1));plus.setOnClickListener(v->changeQty(item,1));int insert=Math.min(2,card.getChildCount());card.addView(row,insert);}
    private void changeQty(Object item,int delta){int q=1;try{q=(int)Math.round(Double.parseDouble(get(item,"qty")));}catch(Exception ignored){}q=Math.max(1,q+delta);set(item,"qty",String.valueOf(q));invokeBase("showWizard");}
    private boolean containsExact(ViewGroup g,String val){for(int i=0;i<g.getChildCount();i++){View v=g.getChildAt(i);if(v instanceof TextView&&val.equals(String.valueOf(((TextView)v).getText()).trim()))return true;if(v instanceof ViewGroup&&containsExact((ViewGroup)v,val))return true;}return false;}

    private void loadCatalogNames(){for(int part=1;part<=6;part++)try{BufferedReader br=new BufferedReader(new InputStreamReader(getAssets().open("catalog_v4_"+part+".tsv")));String line;while((line=br.readLine())!=null){String[] x=line.split("\\t",-1);if(x.length>=2&&!x[1].trim().isEmpty())catalogCategories.put(x[1].trim(),x[0].trim());}br.close();}catch(Exception ignored){}}
    private void interceptCatalogCards(View v){if(!(v instanceof LinearLayout))return;ViewGroup g=(ViewGroup)v;String product=findCatalogName(g);if(product==null)return;if(decorated.contains(v))return;decorated.add(v);final String name=product,cat=catalogCategories.get(product);v.setOnClickListener(x->showRememberingEditor(name,cat));}
    private String findCatalogName(ViewGroup g){for(int i=0;i<g.getChildCount();i++){View c=g.getChildAt(i);if(c instanceof TextView){String s=String.valueOf(((TextView)c).getText()).trim();if(catalogCategories.containsKey(s))return s;}if(c instanceof ViewGroup){String s=findCatalogName((ViewGroup)c);if(s!=null)return s;}}return null;}
    private void showRememberingEditor(String name,String category){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(6),dp(16),0);box.addView(text(name,15,true,NAVY));EditText qty=field(tx("Quantity","الكمية","بڕ"),"1",true);String remembered=lastPrice(name);EditText price=field(tx("Unit price (optional)","سعر الوحدة (اختياري)","نرخی یەکە (ئارەزوومەندانە)"),remembered,true);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(42));ep.topMargin=dp(8);box.addView(qty,ep);box.addView(price,ep);AlertDialog d=new AlertDialog.Builder(this).setTitle(tx("Add material","إضافة مادة","ماددە زیاد بکە")).setView(box).setPositiveButton(tx("Add","إضافة","زیادکردن"),null).setNegativeButton(tx("Cancel","إلغاء","هەڵوەشاندنەوە"),null).create();d.setOnShowListener(z->{Button ok=d.getButton(AlertDialog.BUTTON_POSITIVE);ok.setOnClickListener(v->{String q=qty.getText().toString().trim();if(q.isEmpty())q="1";String p=price.getText().toString().trim();Object it=newItem(name,category,q,p);ArrayList<Object> list=items();if(it!=null)list.add(it);if(!p.isEmpty())rememberPrice(name,p);d.dismiss();invokeBase("showWizard");});});d.show();}
    private EditText field(String hint,String val,boolean num){EditText e=new EditText(this);e.setHint(hint);e.setText(val);e.setTextSize(13);e.setSingleLine(true);e.setPadding(dp(10),0,dp(10),0);e.setBackground(bg(Color.rgb(249,251,253),BORDER,12));e.setGravity((rtl()?Gravity.RIGHT:Gravity.LEFT)|Gravity.CENTER_VERTICAL);if(num)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);return e;}
    private String priceKey(String n){return"last_price_"+Integer.toHexString(n.toLowerCase(Locale.ROOT).hashCode());}private String lastPrice(String n){return getSharedPreferences("offer_studio_prices",MODE_PRIVATE).getString(priceKey(n),"");}private void rememberPrice(String n,String p){getSharedPreferences("offer_studio_prices",MODE_PRIVATE).edit().putString(priceKey(n),p).apply();}
    private void persistVisiblePrices(){for(Object it:items()){String n=get(it,"name"),p=get(it,"price");if(!n.isEmpty()&&!p.isEmpty())rememberPrice(n,p);}}

    private boolean validateForExport(){Object d=draft();ArrayList<String> miss=new ArrayList<>();if(d==null)return false;if(get(d,"client").trim().isEmpty())miss.add(tx("Client name","اسم العميل","ناوی کڕیار"));if(get(d,"phone").trim().isEmpty())miss.add(tx("Phone","رقم الهاتف","تەلەفۆن"));if(get(d,"location").trim().isEmpty())miss.add(tx("Location","الموقع","شوێن"));if(get(d,"capacity").trim().isEmpty())miss.add(tx("System capacity","سعة المنظومة","توانای سیستەم"));if(get(d,"organizer").trim().isEmpty())miss.add(tx("Organizer","منظم الكشف","ڕێکخەر"));if(items().isEmpty())miss.add(tx("At least one material","مادة واحدة على الأقل","لانیکەم یەک ماددە"));if(miss.isEmpty())return true;StringBuilder b=new StringBuilder(tx("Please complete these fields before exporting:","أكمل هذه البيانات قبل التصدير:","پێش هەناردەکردن ئەم زانیارییانە پڕ بکەرەوە:")).append("\n\n");for(String s:miss)b.append("• ").append(s).append("\n");new AlertDialog.Builder(this).setTitle(tx("Missing information","بيانات ناقصة","زانیاری کەمە")).setMessage(b.toString()).setPositiveButton(tx("OK","حسناً","باشە"),null).show();return false;}

    private File makeDataFile(){Object d=draft();if(d==null)return null;try{JSONObject root=new JSONObject();root.put("format","IGP Organizer Form Data");root.put("version","6.3.0");root.put("client",get(d,"client"));root.put("phone",get(d,"phone"));root.put("location",get(d,"location"));root.put("date",get(d,"date"));root.put("system_type",get(d,"system"));root.put("capacity",get(d,"capacity"));root.put("phase",get(d,"phase"));root.put("organizer",get(d,"organizer"));root.put("notes",get(d,"notes"));JSONArray a=new JSONArray();for(Object it:items()){JSONObject x=new JSONObject();x.put("category",get(it,"category"));x.put("name",get(it,"name"));x.put("quantity",get(it,"qty"));x.put("unit_price",get(it,"price"));x.put("line_total",lineTotal(it).toPlainString());a.put(x);}root.put("items",a);root.put("estimated_total",grand().toPlainString());root.put("currency",settings().getString("currency","USD"));File dir=getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS);File out=new File(dir,baseFileName(d)+"_data.json");FileOutputStream os=new FileOutputStream(out);os.write(root.toString(2).getBytes("UTF-8"));os.close();return out;}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();return null;}}

    private File makePdf63(){Object d=draft();if(d==null)return null;try{File dir=getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS);File out=new File(dir,baseFileName(d)+".pdf");PdfDocument doc=new PdfDocument();Writer w=new Writer(doc);w.newPage();w.clientSection(d);w.systemSection(d);w.materialSection();w.organizerSection(d);w.notesSection(d);w.finish();FileOutputStream os=new FileOutputStream(out);doc.writeTo(os);os.close();doc.close();return out;}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();return null;}}
    private class Writer{PdfDocument doc;PdfDocument.Page page;Canvas c;Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);int y=0,pageNo=0;Writer(PdfDocument d){doc=d;}void newPage(){if(page!=null)doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());c=page.getCanvas();c.drawColor(Color.WHITE);header();}void header(){Bitmap logo=loadLogo63();if(logo!=null){float s=Math.min(86f/logo.getWidth(),55f/logo.getHeight());int ww=(int)(logo.getWidth()*s),hh=(int)(logo.getHeight()*s);c.drawBitmap(logo,null,new Rect(42,24,42+ww,24+hh),null);}String company=settings().getString("company_name","Infinity Green Power");draw(company.toUpperCase(Locale.ROOT),150,38,19,true,NAVY);draw(tx("Organizer Preliminary Solar Form","استمارة أولية للمنظومة الشمسية","فۆرمی سەرەتایی سیستەمی خۆرەوی"),150,61,10,true,TEAL_DARK);draw(tx("Date","التاريخ","بەروار")+": "+get(draft(),"date"),150,78,8,false,MUTED);p.setColor(TEAL);c.drawRect(40,94,555,97,p);y=113;}void ensure(int n){if(y+n>790)newPage();}void section(String s,int need){ensure(need);p.setColor(NAVY);c.drawRoundRect(40,y,555,y+24,7,7,p);draw(s,50,y+16,10,true,Color.WHITE);y+=32;}void row(String k,String v){ensure(27);draw(k,45,y+15,8,true,MUTED);draw(v,180,y+15,10,false,NAVY);p.setColor(BORDER);c.drawLine(40,y+23,555,y+23,p);y+=27;}void clientSection(Object d){section(tx("Client","العميل","کڕیار"),135);row(tx("Client","العميل","کڕیار"),get(d,"client"));row(tx("Phone","الهاتف","تەلەفۆن"),get(d,"phone"));row(tx("Location","الموقع","شوێن"),get(d,"location"));row(tx("Date","التاريخ","بەروار"),get(d,"date"));}void systemSection(Object d){section(tx("System","المنظومة","سیستەم"),110);row(tx("Type","النوع","جۆر"),get(d,"system"));row(tx("Capacity","السعة","توانا"),get(d,"capacity"));row(tx("Phase","الطور","فاز"),get(d,"phase"));}void materialSection(){section(tx("Materials","المواد","ماددە"),Math.min(260,65+items().size()*27));draw(tx("Item","المادة","ماددە"),45,y+14,8,true,TEAL_DARK);draw(tx("Qty","الكمية","بڕ"),355,y+14,8,true,TEAL_DARK);if(settings().getBoolean("showPrices",true)){draw(tx("Price","السعر","نرخ"),425,y+14,8,true,TEAL_DARK);draw(tx("Total","المجموع","کۆ"),500,y+14,8,true,TEAL_DARK);}y+=22;for(Object it:items()){ensure(27);draw(trim(get(it,"name"),43),45,y+15,9,false,NAVY);draw(get(it,"qty"),355,y+15,9,false,NAVY);if(settings().getBoolean("showPrices",true)){draw(get(it,"price"),425,y+15,9,false,NAVY);draw(money.format(lineTotal(it)),500,y+15,9,false,NAVY);}p.setColor(BORDER);c.drawLine(40,y+23,555,y+23,p);y+=27;}if(settings().getBoolean("pdf_show_total",true)){ensure(30);draw(tx("Estimated total","المجموع التقديري","کۆی خەمڵاندراو")+": "+settings().getString("currency","USD")+" "+money.format(grand()),45,y+18,11,true,TEAL_DARK);y+=30;}}void organizerSection(Object d){section(tx("Organizer","منظم الكشف","ڕێکخەر"),64);row(tx("Organizer","منظم الكشف","ڕێکخەر"),get(d,"organizer"));}void notesSection(Object d){String notes=get(d,"notes");section(tx("Load / notes","التحميل / الملاحظات","بار / تێبینی"),Math.min(180,55+wrap(notes,75).size()*18));for(String line:wrap(notes,75)){ensure(19);draw(line,45,y+14,9,false,NAVY);y+=18;}}void finish(){if(page!=null){draw(settings().getString("company_name","Infinity Green Power")+" · Organizer Form",40,820,8,false,TEAL_DARK);doc.finishPage(page);page=null;}}void draw(String s,float x,float yy,float sz,boolean bold,int color){p.setColor(color);p.setTextSize(sz);p.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);p.setTextAlign(Paint.Align.LEFT);c.drawText(s==null?"":s,x,yy,p);}String trim(String s,int n){return s==null?"":(s.length()>n?s.substring(0,n-1)+"…":s);}}

    private Bitmap loadLogo63(){String s=settings().getString("logo_uri","");if(s.isEmpty())return null;try{InputStream in=getContentResolver().openInputStream(Uri.parse(s));Bitmap b=BitmapFactory.decodeStream(in);if(in!=null)in.close();return b;}catch(Exception e){return null;}}
    private ArrayList<String> wrap(String s,int max){ArrayList<String> o=new ArrayList<>();if(s==null||s.trim().isEmpty()){o.add("—");return o;}for(String raw:s.split("\\n")){String line="";for(String word:raw.trim().split("\\s+")){if((line+" "+word).trim().length()>max){if(!line.isEmpty())o.add(line);line=word;}else line=(line+" "+word).trim();}if(!line.isEmpty())o.add(line);}return o;}
    private String baseFileName(Object d){String c=get(d,"client").replaceAll("[^A-Za-z0-9\\u0600-\\u06FF_-]+","_");if(c.isEmpty())c="Client";String cap=get(d,"capacity").replaceAll("[^A-Za-z0-9]+","");return c+"_"+(cap.isEmpty()?"Solar":cap)+"_"+get(d,"date").replace("/","-");}
    private void shareFile(File f,String mime,String title){Uri u=new Uri.Builder().scheme("content").authority(getPackageName()+".provider").appendPath(f.getName()).build();Intent i=new Intent(Intent.ACTION_SEND);i.setType(mime);i.putExtra(Intent.EXTRA_STREAM,u);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,title));}

    @Override protected void onActivityResult(int req,int res,Intent data){if((req==SAVE_PDF_63||req==SAVE_DATA_63)&&res==RESULT_OK&&data!=null&&data.getData()!=null){File src=req==SAVE_PDF_63?pendingPdf:pendingData;if(src!=null)try{InputStream in=new FileInputStream(src);OutputStream out=getContentResolver().openOutputStream(data.getData());byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();if(out!=null)out.close();Toast.makeText(this,tx("Saved","تم الحفظ","پاشەکەوت کرا"),Toast.LENGTH_SHORT).show();}catch(Exception ignored){}return;}super.onActivityResult(req,res,data);}

    @SuppressWarnings("unchecked") private ArrayList<Object> items(){try{Field f=OrganizerRebuildActivity.class.getDeclaredField("items");f.setAccessible(true);return(ArrayList<Object>)f.get(this);}catch(Exception e){return new ArrayList<>();}}
    private Object draft(){try{Field f=OrganizerRebuildActivity.class.getDeclaredField("draft");f.setAccessible(true);return f.get(this);}catch(Exception e){return null;}}
    private SharedPreferences settings(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE);}private String get(Object o,String n){if(o==null)return"";try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);Object v=f.get(o);return v==null?"":String.valueOf(v);}catch(Exception e){return"";}}private void set(Object o,String n,String v){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}catch(Exception ignored){}}
    private Object findItemForCard(ViewGroup g){for(Object it:items()){String n=get(it,"name");if(!n.isEmpty()&&containsExact(g,n))return it;}return null;}
    private Object newItem(String n,String c,String q,String p){try{Class<?> k=Class.forName("com.infinitygreenpower.solarform.OrganizerRebuildActivity$LineItem");Constructor<?> ct=k.getDeclaredConstructor();ct.setAccessible(true);Object o=ct.newInstance();set(o,"name",n);set(o,"category",c==null?"":c);set(o,"qty",q);set(o,"price",p);return o;}catch(Exception e){return null;}}
    private BigDecimal num(String s){try{return new BigDecimal(s==null||s.trim().isEmpty()?"0":s.replace(",","").replace("$","").trim());}catch(Exception e){return BigDecimal.ZERO;}}private BigDecimal lineTotal(Object it){BigDecimal q=num(get(it,"qty"));if(q.signum()==0)q=BigDecimal.ONE;return q.multiply(num(get(it,"price")));}private BigDecimal grand(){BigDecimal x=BigDecimal.ZERO;for(Object it:items())x=x.add(lineTotal(it));return x;}
    private void invokeBase(String n){try{Method m=OrganizerRebuildActivity.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(this);}catch(Exception ignored){}}
}
